mapper.select:
SELECT COUNT(1) FROM (
    SELECT b.id
    FROM blogs b
    WHERE b.status = 1
      AND b.id NOT IN (
          SELECT DISTINCT blog_id FROM user_behavior_log
          WHERE user_id = #{userId}
            AND behavior_type IN ('like', 'favorite', 'comment')
      )
      AND b.id NOT IN (
          SELECT DISTINCT blog_id FROM user_behavior_log
          WHERE user_id = #{userId}
            AND behavior_type = 'view'
            AND created_at >= NOW() - INTERVAL '7 days'
      )
) sub

SELECT COUNT(1) FROM user_behavior_log
WHERE user_id = #{userId}
  AND blog_id = #{blogId}
  AND behavior_type = #{behaviorType}
